void insert_into_sorted_leaf(Node* leaf, int key, FILE* filePtr) {
    // Ensure the node is a leaf
    if (!leaf->isLeaf) {
        return; // or assert(false) in debug mode
    }

    // Find the position to insert the key to maintain sorted order
    auto it = std::lower_bound(leaf->keys.begin(), leaf->keys.end(), key);
    int pos = it - leaf->keys.begin();

    // Insert the key at the specified position
    leaf->keys.insert(it, key);

    // Insert the data pointer at the same position
    leaf->ptr2TreeOrData.dataPtr.insert(leaf->ptr2TreeOrData.dataPtr.begin() + pos, filePtr);
}

